# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
# Deploys the Datadog Agent to a Kubernetes cluster using the official Helm chart.
# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

# ---------------------------------------------------------------------------------------------------------------------
# SET TERRAFORM REQUIREMENTS FOR RUNNING THIS MODULE
# ---------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.3.0, < 2.0"

  required_providers {
    helm = {
      source  = "hashicorp/helm"
      version = "~> 2.0"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "~> 2.0"
    }
  }
}

locals {
  apm_rules = file("${path.module}/processing-rules/${var.env}/apm.json")
  log_rules = file("${path.module}/processing-rules/${var.env}/rules.json")
  nowrds_instance = var.enable_nowrds_monitoring ? (<<-EON
    - dbm: true
      ssl: allow
      host: "%%env_NOWRDS_HOST%%"
      port: "%%env_NOWRDS_PORT%%"
      username: "%%env_NOWRDS_USERNAME%%"
      password: "%%env_NOWRDS_PASSWORD%%"
      collect_schemas:
        enabled: true
      database_autodiscovery:
        enabled: true
      tags:
        - "dbinstanceidentifier:%%env_NOWRDS_INSTANCE_NAME%%"
        - "env:%%env_DD_ENV%%"
  EON
  ) : null
}
# ---------------------------------------------------------------------------------------------------------------------
# CREATE A NAMESPACE
# ---------------------------------------------------------------------------------------------------------------------
resource "kubernetes_namespace" "this" {
  count = var.create_namespace ? 1 : 0
  metadata {
    name = var.namespace
  }
}

resource "kubernetes_config_map" "datadog_processing_rules" {
  metadata {
    name      = "rules-config"
    namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
  }
  data = {
    //"apm"  = local.apm_rules
    "apm" = file("${path.module}/processing-rules/${var.env}/apm.json")
    //"logs" = local.log_rules
    "logs" = file("${path.module}/processing-rules/${var.env}/rules.json")
  }
  depends_on = [kubernetes_namespace.this]
}

resource "kubernetes_manifest" "external-secret-dd-api-key" {
  manifest = {
    apiVersion = "external-secrets.io/v1"
    kind       = "ExternalSecret"
    metadata = {
      name      = "datadog-api-key"
      namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
    }
    spec = {
      refreshInterval = "1h0m0s"
      secretStoreRef = {
        name = "vault"
        kind = "ClusterSecretStore"
      }
      target = {
        name           = "datadog-api-key"
        creationPolicy = "Owner"
      }
      data = [{
        secretKey = "api-key"
        remoteRef = {
          key      = "saas/infrastructure/datadog-api-key"
          property = "apiKey"
        }
      }]
    }
  }
}

resource "kubernetes_manifest" "external-secret-dd-api-token" {
  manifest = {
    apiVersion = "external-secrets.io/v1"
    kind       = "ExternalSecret"
    metadata = {
      name      = "datadog-clusteragent-token"
      namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
    }
    spec = {
      refreshInterval = "1h0m0s"
      secretStoreRef = {
        name = "vault"
        kind = "ClusterSecretStore"
      }
      target = {
        name           = "datadog-clusteragent-token"
        creationPolicy = "Owner"
      }
      data = [{
        secretKey = "token"
        remoteRef = {
          key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
          property = "token"
        }
      }]
    }
  }
}

resource "kubernetes_manifest" "external-secret" {
  count = (var.enable_mrds_monitoring || var.enable_nowrds_monitoring) ? 1 : 0

  manifest = {
    apiVersion = "external-secrets.io/v1"
    kind       = "ExternalSecret"
    metadata = {
      name      = "datadog-env"
      namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
    }
    spec = {
      refreshInterval = "1h0m0s"
      secretStoreRef = {
        name = "vault"
        kind = "ClusterSecretStore"
      }
      target = {
        name           = "datadog-env"
        creationPolicy = "Owner"
      }
      data = concat(var.enable_mrds_monitoring ? [
        {
          secretKey = "MRDS_HOST"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "rds-host"
          }
        },
        {
          secretKey = "MRDS_PORT"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "rds-port"
          }
        },
        {
          secretKey = "MRDS_USERNAME"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "rds-username"
          }
        },
        {
          secretKey = "MRDS_PASSWORD"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "rds-password"
          }
        },
        {
          secretKey = "MRDS_REGION"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "rds-region"
          }
        },
        {
          secretKey = "MRDS_INSTANCE_NAME"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "rds-instance"
          }
        },
        ] : [], var.enable_nowrds_monitoring ? [
        {
          secretKey = "NOWRDS_HOST"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "NOWRDS_HOST"
          }
        },
        {
          secretKey = "NOWRDS_PORT"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "NOWRDS_PORT"
          }
        },
        {
          secretKey = "NOWRDS_USERNAME"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "NOWRDS_USERNAME"
          }
        },
        {
          secretKey = "NOWRDS_PASSWORD"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "NOWRDS_PASSWORD"
          }
        },
        {
          secretKey = "NOWRDS_INSTANCE_NAME"
          remoteRef = {
            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
            property = "NOWRDS_INSTANCE_NAME"
          }
        }
      ] : [])
    }
  }
  depends_on = [kubernetes_namespace.this]
}
# ---------------------------------------------------------------------------------------------------------------------
# DEPLOY A HELM CHART
# ---------------------------------------------------------------------------------------------------------------------
resource "helm_release" "this" {
  name = var.name
  #namespace = kubernetes_namespace.this.metadata[0].name
  namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
  wait      = false # Set to true if you want Terraform to wait for resources to be ready

  repository = "https://helm.datadoghq.com"
  chart      = "datadog"
  version    = var.chart_version
  values = [
    templatefile("${path.module}/values.yaml.tftpl", {
      cluster_name               = var.cluster_name
      env                        = var.env == "staging" ? "nonprod" : var.env
      global_segment             = var.global_segment
      image_tag                  = var.image_tag
      watch_namespace            = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
      tags                       = concat(["global_segment:${var.global_segment}"], var.datadog_tags)
      agents_priority_class_name = var.agents_priority_class_name

      apm_enabled = var.apm_enabled

      container_exclude      = var.container_exclude
      container_exclude_logs = var.container_exclude_logs

      enable_mrds_monitoring         = var.enable_mrds_monitoring
      enable_nowrds_monitoring       = var.enable_nowrds_monitoring
      enable_now_obfusicator_options = var.enable_now_obfusicator_options
      now_obfusicator_options        = var.now_obfusicator_options

      datadog_api_key_secret_name     = var.datadog_api_key_secret_name
      cluster_agent_token_secret_name = var.cluster_agent_token_secret_name
      log_level                       = var.log_level

      logs_intake_url = var.logs_intake_url
    })
  ]

  depends_on = [
    kubernetes_namespace.this,
    kubernetes_manifest.external-secret,
    kubernetes_manifest.external-secret-dd-api-key,
    kubernetes_manifest.external-secret-dd-api-token
  ]
}

module "netpol" {
  source = "git@gitlab.infrastructure.immuta.io:infrastructure/terraform/internal-modules/kubernetes/security/network-policy.git?ref=v1.1.0"

  name             = join("-", [var.name, "netpol"])
  namespace        = var.namespace
  network_policies = local.netpols

  tags = merge(var.tags, { "sourceModule" = "/internal-modules/kubernetes/monitoring/datadog" })

  depends_on = [
    kubernetes_namespace.this
  ]
}

