  netpols = {
    "vector" = local.vector_netpol
  }
  vector_netpol = {
    endpointSelector = {
      matchLabels = {
        "app.kubernetes.io/name" = "vector"
      }
    }
    ingress = [
      {
        # OTLP from any cluster-internal sender (primarily otel-collector).
        # Port 8282 is the OPW-compatible Datadog Agent intake (datadog_agent source).
        fromEntities = ["cluster"]
        toPorts = [{
          ports = [
            { port = "4317" },
            { port = "4318" },
            { port = "8282" },
          ]
        }]
      },
      {
        # Vector self-metrics scrape (Prometheus operator, Datadog Agent, etc.).
        fromEntities = ["cluster"]
        toPorts = [{
          ports = [{ port = "8686" }]
        }]
      },
      {
        # kubelet health probes and DD Agent (useHostNetwork: true) from the node.
        fromEntities = ["host"]
        toPorts = [{
          ports = [
            { port = "4317" },
            { port = "4318" },
            { port = "8282" },
            { port = "8686" },
          ]
        }]
      },
      {
        fromEntities = ["kube-apiserver"]
      }
    ]
    egress = [
      {
        # Datadog SaaS HTTPS for logs/traces/metrics sinks.
        toEntities = ["world"]
        toPorts = [{
          ports = [{ port = "443" }]
        }]
      },
      {
        toEntities = ["kube-apiserver"]
      },
      {
        # DNS resolution + service discovery (CoreDNS lives here).
        toEntities = ["cluster"]
      }
    ]
  }
}

